source='''from collections import Counter


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    edge_counts = Counter(
        value
        for r in range(h)
        for value in (grid[r][0], grid[r][-1])
        if value != background
    )
    if not edge_counts:
        return out
    rail = edge_counts.most_common(1)[0][0]
    signal_colors = [value for value in counts if value not in (background, rail)]
    if not signal_colors:
        return out
    signal = max(signal_colors, key=lambda value: counts[value])

    left_rows = [r for r in range(h) if grid[r][0] == rail]
    right_rows = [r for r in range(h) if grid[r][-1] == rail]

    def runs(rows):
        if not rows:
            return []
        result = []
        start = previous = rows[0]
        for row in rows[1:]:
            if row != previous + 1:
                result.append((start, previous))
                start = row
            previous = row
        result.append((start, previous))
        return result

    left_runs, right_runs = runs(left_rows), runs(right_rows)
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == signal]
    candidates = [('L', a, b) for a, b in left_runs] + [('R', a, b) for a, b in right_runs]
    if not candidates:
        return out

    side, start, end = max(
        candidates,
        key=lambda run: sum(run[1] <= r <= run[2] for r, _ in points),
    )
    active_offsets = sorted({r - start for r, _ in points if start <= r <= end})

    # Signal marks extend horizontally toward the edge rail on their side.
    for r, c in points:
        if not start <= r <= end:
            continue
        if side == 'L':
            for x in range(1, c):
                if out[r][x] in (background, signal):
                    out[r][x] = signal
        else:
            for x in range(c + 1, w - 1):
                if out[r][x] in (background, signal):
                    out[r][x] = signal
        out[r][c] = 4

    # Copy each active row offset to the opposite edge run.
    opposite_runs = [
        (a, b, other_side)
        for other_side, edge_runs in (('R', right_runs), ('L', left_runs))
        for a, b in edge_runs
        if other_side != side
    ]
    if opposite_runs:
        other_start, other_end, other_side = max(
            opposite_runs, key=lambda run: min(run[1] - run[0], end - start)
        )
        for offset in active_offsets:
            r = other_start + offset
            if r > other_end:
                continue
            columns = range(0, w - 1) if other_side == 'R' else range(1, w)
            for c in columns:
                if out[r][c] == background:
                    out[r][c] = signal
    return out
'''
